{
  "root": "main_stack",
  "state": {
    "lens_differences": [
      {
        "Category": "Focal Length",
        "Prime Lens": "Fixed focal length (e.g., 50mm, 35mm, 85mm). You \"zoom with your feet\" by moving closer or further from your subject.",
        "Zoom Lens": "Variable focal length (e.g., 18-55mm, 70-200mm). You can change your field of view without moving your position."
      },
      {
        "Category": "Image Quality",
        "Prime Lens": "Often delivers superior image sharpness, contrast, and better performance in low light due to simpler optical design and wider maximum apertures.",
        "Zoom Lens": "Image quality can be very good, especially with higher-end models, but generally, a prime lens at its sweet spot will outperform a zoom lens at the same focal length."
      },
      {
        "Category": "Aperture (Light Gathering)",
        "Prime Lens": "Typically features a wider maximum aperture (e.g., f/1.8, f/1.4). Excellent for low-light and creating beautiful shallow depth of field (bokeh).",
        "Zoom Lens": "Usually has a narrower maximum aperture (e.3.5-5.6). Gathers less light, less ideal for dim environments and less dramatic background blur."
      },
      {
        "Category": "Size & Weight",
        "Prime Lens": "Generally smaller, lighter, and more compact, making them easier to carry around.",
        "Zoom Lens": "Typically larger and heavier, especially lenses with a wide zoom range or constant wide aperture."
      },
      {
        "Category": "Cost",
        "Prime Lens": "Entry-level prime lenses (like a 50mm f/1.8) are often very affordable. High-end primes can be expensive.",
        "Zoom Lens": "Kit zoom lenses (e.g., 18-55mm) are often included with cameras and are budget-friendly. Versatile or professional-grade zoom lenses can be significantly more expensive."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h2",
        "intro_text",
        "divider_1",
        "core_diff_h2",
        "core_diff_intro_text",
        "diff_table",
        "divider_2",
        "prime_lens_section",
        "divider_3",
        "zoom_lens_section",
        "divider_4",
        "quick_actions_h2",
        "quick_actions_stack",
        "divider_5",
        "sources_h2",
        "sources_stack"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Understanding DSLR Lenses: Prime vs. Zoom",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Choosing the right lens is a key step for any beginner photographer. Lenses are broadly categorized into two main types: prime lenses and zoom lenses, each offering distinct characteristics that influence your photography.",
        "variant": "body"
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "core_diff_h2": {
      "type": "Text",
      "props": {
        "text": "Prime vs. Zoom Lenses: Core Differences",
        "variant": "h2"
      },
      "children": []
    },
    "core_diff_intro_text": {
      "type": "Text",
      "props": {
        "text": "Here's a breakdown of the key distinctions to help you decide which lens is best suited for various situations:",
        "variant": "body"
      },
      "children": []
    },
    "diff_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "Category",
            "label": "Category"
          },
          {
            "key": "Prime Lens",
            "label": "Prime Lens"
          },
          {
            "key": "Zoom Lens",
            "label": "Zoom Lens"
          }
        ],
        "statePath": "/lens_differences",
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "Category",
        "highlightColumns": [
          "Prime Lens",
          "Zoom Lens"
        ]
      },
      "children": []
    },
    "divider_2": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "prime_lens_section": {
      "type": "Card",
      "props": {
        "padding": 16,
        "gap": "md"
      },
      "children": [
        "prime_lens_header_stack",
        "prime_intro_text",
        "prime_advantages_h3",
        "prime_advantages_list",
        "prime_disadvantages_h3",
        "prime_disadvantages_list",
        "prime_use_cases_h3",
        "prime_use_cases_list"
      ]
    },
    "prime_lens_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "prime_icon",
        "prime_h2"
      ]
    },
    "prime_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000344_01_1_camera.svg"
      },
      "children": []
    },
    "prime_h2": {
      "type": "Text",
      "props": {
        "text": "Prime Lenses: Focus & Clarity",
        "variant": "h2"
      },
      "children": []
    },
    "prime_intro_text": {
      "type": "Text",
      "props": {
        "text": "Prime lenses have a fixed focal length, meaning they don't zoom. They are celebrated for their optical quality and ability to perform well in challenging light.",
        "variant": "body"
      },
      "children": []
    },
    "prime_advantages_h3": {
      "type": "Text",
      "props": {
        "text": "Advantages:",
        "variant": "h3"
      },
      "children": []
    },
    "prime_advantages_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "prime_adv_1",
        "prime_adv_2",
        "prime_adv_3",
        "prime_adv_4",
        "prime_adv_5"
      ]
    },
    "prime_adv_1": {
      "type": "Text",
      "props": {
        "text": "Superior Image Quality: Often sharper with better contrast and color rendition.",
        "variant": "body"
      },
      "children": []
    },
    "prime_adv_2": {
      "type": "Text",
      "props": {
        "text": "Excellent Low-Light Performance: Wider apertures (lower f-numbers) allow more light, enabling faster shutter speeds in dim conditions and reducing noise.",
        "variant": "body"
      },
      "children": []
    },
    "prime_adv_3": {
      "type": "Text",
      "props": {
        "text": "Beautiful Background Blur (Bokeh): Wide apertures create a shallow depth of field, making your subject stand out against a creamy, blurred background.",
        "variant": "body"
      },
      "children": []
    },
    "prime_adv_4": {
      "type": "Text",
      "props": {
        "text": "Compact & Lightweight: Easier to carry for extended periods.",
        "variant": "body"
      },
      "children": []
    },
    "prime_adv_5": {
      "type": "Text",
      "props": {
        "text": "Encourages Creativity: Forces you to think about composition and move around to frame your shot.",
        "variant": "body"
      },
      "children": []
    },
    "prime_disadvantages_h3": {
      "type": "Text",
      "props": {
        "text": "Disadvantages:",
        "variant": "h3"
      },
      "children": []
    },
    "prime_disadvantages_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "prime_disadv_1",
        "prime_disadv_2"
      ]
    },
    "prime_disadv_1": {
      "type": "Text",
      "props": {
        "text": "Less Versatile: You need to physically move to change your composition, or swap lenses if you need a different focal length.",
        "variant": "body"
      },
      "children": []
    },
    "prime_disadv_2": {
      "type": "Text",
      "props": {
        "text": "Can Be Limiting: Not ideal for situations where you can't move freely (e.g., concerts, wildlife from a distance).",
        "variant": "body"
      },
      "children": []
    },
    "prime_use_cases_h3": {
      "type": "Text",
      "props": {
        "text": "Typical Use Cases:",
        "variant": "h3"
      },
      "children": []
    },
    "prime_use_cases_list": {
      "type": "Text",
      "props": {
        "text": "Portraits, street photography, low-light photography, astrophotography, product photography, and any situation where sharp images and artistic background blur are desired.",
        "variant": "body"
      },
      "children": []
    },
    "divider_3": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "zoom_lens_section": {
      "type": "Card",
      "props": {
        "padding": 16,
        "gap": "md"
      },
      "children": [
        "zoom_lens_header_stack",
        "zoom_intro_text",
        "zoom_advantages_h3",
        "zoom_advantages_list",
        "zoom_disadvantages_h3",
        "zoom_disadvantages_list",
        "zoom_use_cases_h3",
        "zoom_use_cases_list"
      ]
    },
    "zoom_lens_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "zoom_icon",
        "zoom_h2"
      ]
    },
    "zoom_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000344_01_2_zoom-in.svg"
      },
      "children": []
    },
    "zoom_h2": {
      "type": "Text",
      "props": {
        "text": "Zoom Lenses: Flexibility & Range",
        "variant": "h2"
      },
      "children": []
    },
    "zoom_intro_text": {
      "type": "Text",
      "props": {
        "text": "Zoom lenses allow you to change your focal length, giving you the flexibility to capture various perspectives without switching lenses. They are often the go-to choice for their convenience.",
        "variant": "body"
      },
      "children": []
    },
    "zoom_advantages_h3": {
      "type": "Text",
      "props": {
        "text": "Advantages:",
        "variant": "h3"
      },
      "children": []
    },
    "zoom_advantages_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "zoom_adv_1",
        "zoom_adv_2",
        "zoom_adv_3"
      ]
    },
    "zoom_adv_1": {
      "type": "Text",
      "props": {
        "text": "High Versatility: Cover multiple focal lengths in one lens, reducing the need to carry several lenses.",
        "variant": "body"
      },
      "children": []
    },
    "zoom_adv_2": {
      "type": "Text",
      "props": {
        "text": "Convenience: Great for travel, events, or situations where you need to react quickly to changing scenes and can't always move your position.",
        "variant": "body"
      },
      "children": []
    },
    "zoom_adv_3": {
      "type": "Text",
      "props": {
        "text": "Good for Beginners: Allows experimentation with different focal lengths to discover preferred styles.",
        "variant": "body"
      },
      "children": []
    },
    "zoom_disadvantages_h3": {
      "type": "Text",
      "props": {
        "text": "Disadvantages:",
        "variant": "h3"
      },
      "children": []
    },
    "zoom_disadvantages_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "zoom_disadv_1",
        "zoom_disadv_2",
        "zoom_disadv_3",
        "zoom_disadv_4"
      ]
    },
    "zoom_disadv_1": {
      "type": "Text",
      "props": {
        "text": "Generally Less Sharp: While modern zooms are very good, they typically don't match the edge-to-edge sharpness of a comparable prime lens.",
        "variant": "body"
      },
      "children": []
    },
    "zoom_disadv_2": {
      "type": "Text",
      "props": {
        "text": "Worse Low-Light Performance: Often have narrower maximum apertures, limiting their effectiveness in dim conditions and making it harder to achieve significant background blur.",
        "variant": "body"
      },
      "children": []
    },
    "zoom_disadv_3": {
      "type": "Text",
      "props": {
        "text": "Larger & Heavier: Can add considerable weight and bulk to your camera bag.",
        "variant": "body"
      },
      "children": []
    },
    "zoom_disadv_4": {
      "type": "Text",
      "props": {
        "text": "Potential for Distortion/Aberrations: More complex optical design can sometimes lead to more optical imperfections.",
        "variant": "body"
      },
      "children": []
    },
    "zoom_use_cases_h3": {
      "type": "Text",
      "props": {
        "text": "Typical Use Cases:",
        "variant": "h3"
      },
      "children": []
    },
    "zoom_use_cases_list": {
      "type": "Text",
      "props": {
        "text": "Travel photography, event photography, landscape photography (where a range of views is useful), sports, wildlife, and general all-around photography where flexibility is key.",
        "variant": "body"
      },
      "children": []
    },
    "divider_4": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "explore_lenses_button",
        "basics_guide_button"
      ]
    },
    "explore_lenses_button": {
      "type": "Button",
      "props": {
        "label": "Explore Beginner Lenses"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.adorama.com/l/Lenses/DSLR-Lenses/Beginner-Lenses"
          }
        }
      },
      "children": []
    },
    "basics_guide_button": {
      "type": "Button",
      "props": {
        "label": "Photography Basics Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bhphotovideo.com/explora/photography/buying-guide/understanding-camera-lenses"
          }
        }
      },
      "children": []
    },
    "divider_5": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_1_button",
        "source_2_button"
      ]
    },
    "source_1_button": {
      "type": "Button",
      "props": {
        "label": "Beginner's Guide to Photography Lenses",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bhphotovideo.com/explora/photography/buying-guide/understanding-camera-lenses"
          }
        }
      },
      "children": []
    },
    "source_2_button": {
      "type": "Button",
      "props": {
        "label": "Prime vs. Zoom Lens Explained",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.adorama.com/alc/prime-vs-zoom-lens/"
          }
        }
      },
      "children": []
    }
  }
}
